(217667, 12552, 4388, '<td valign="top">the yellow is great but the lighting on one side is distracting.</td>', 'the yellow is great but the lighting on one side is distracting.', '2003-02-17 17:21:17.000000', NULL, 1),
(217668, 12395, 6097, '<td valign="top">Gorgeous!  Well done!  I would hang this on my wall.  I really like the thin border with this.  I think it really adds something to the shot.  Beautiful!  Definitely one of my favorites in this challenge and on the DPChallenge site so far.</td>', 'Gorgeous!  Well done!  I would hang this on my wall.  I really like the thin border with this.  I think it really adds something to the shot.  Beautiful!  Definitely one of my favorites in this challenge and on the DPChallenge site so far.', '2003-02-17 17:21:42.000000', NULL, 1),
(217670, 12703, 4906, '<td valign="top">A square frame may have been good for this.</td>', 'A square frame may have been good for this.', '2003-02-17 17:22:41.000000', NULL, 1),
(217671, 12365, 4906, '<td valign="top">Snigger :)</td>', 'Snigger :)', '2003-02-17 17:23:05.000000', NULL, 1),
