(221388, 12648, 3111, '<td valign="top">Lose the border, I think this works without it.  At least connect the border with the line you drew with the highlighter to make it look like one line, if you have the opportunity.</td>', 'Lose the border, I think this works without it.  At least connect the border with the line you drew with the highlighter to make it look like one line, if you have the opportunity.', '2003-02-22 22:17:30.000000', NULL, 1),
(221391, 12712, 6791, '<td valign="top">Awesome title! Very funny</td>', 'Awesome title! Very funny', '2003-02-22 22:23:30.000000', NULL, 1),
